package com.mohymods.kingdomsmp.economy;
import static org.junit.jupiter.api.Assertions.*;
import com.mohymods.kingdomsmp.profession.*;
import java.nio.file.Path;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
/** Pure trusted canonical-boundary model; native production is independently exercised in dedicated servers. */
class BrewQuotaReceiptTest {
 @TempDir Path path;UUID player=UUID.randomUUID();
 EconomyStore earlierBand()throws Exception{var s=EconomyStore.open(path);s.changeProfession(UUID.randomUUID(),player,"enroll","","alchemist");s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),player,"kingdom_smp:alchemist/a01","Trusted native laboratory boundary model");for(String q:List.of("a02","a03","a04","a05","a06")){String id="kingdom_smp:alchemist/"+q;var operation=UUID.randomUUID();var item=BrewOutputStoreTest.potion(s.id(),operation,BrewQuests.get(id).output());s.issueNativeOutput(operation,player,id,item);var p=s.prepareNativeOutputDelivery(UUID.randomUUID(),player,id,Map.of(operation,item),1);s.recoverItem(new EconomyStore.Receipt(s.id(),p.sequence()));}var ingredient=new CompoundTag();ingredient.putString("id","minecraft:glass_bottle");ingredient.putInt("count",1);for(long day=0;day<3;day++){var p=s.prepareContract(UUID.randomUUID(),player,"alchemist","daily",day,1,10,2000,ingredient,5);s.recoverItem(new EconomyStore.Receipt(s.id(),p.sequence()));}s.completeCommissionQuest(UUID.randomUUID(),player,"kingdom_smp:alchemist/a07",3);s.approveProfessionInspection(UUID.randomUUID(),UUID.randomUUID(),player,"kingdom_smp:alchemist/a08","Trusted earlier complete native lab assessment boundary model");return s;}
 @Test void rejectedMonocultureSpendsNothingAndBalancedCancelCommitArchiveStayExactlyOnce()throws Exception{var s=earlierBand();String quest=BrewQuests.UNDERWATER;Map<UUID,CompoundTag> water=new LinkedHashMap<>();for(int n=0;n<16;n++){var id=UUID.randomUUID();var item=BrewOutputStoreTest.potion(s.id(),id,"water_breathing");s.issueNativeOutput(id,player,quest,item);water.put(id,item);}assertThrows(IllegalArgumentException.class,()->s.prepareNativeOutputDelivery(UUID.randomUUID(),player,quest,water,16));assertEquals(800,s.professions(player).track(Profession.ALCHEMIST).xp());for(var row:water.entrySet())assertTrue(s.matchesNativeOutput(row.getKey(),player,quest,row.getValue()));Map<UUID,CompoundTag> chosen=new LinkedHashMap<>();water.entrySet().stream().limit(8).forEach(e->chosen.put(e.getKey(),e.getValue()));for(int n=0;n<8;n++){var id=UUID.randomUUID();var item=BrewOutputStoreTest.potion(s.id(),id,"night_vision");s.issueNativeOutput(id,player,quest,item);chosen.put(id,item);}var pending=s.prepareNativeOutputDelivery(UUID.randomUUID(),player,quest,chosen,16);assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.previousReceipt())));assertEquals(800,s.professions(player).track(Profession.ALCHEMIST).xp());pending=s.prepareNativeOutputDelivery(UUID.randomUUID(),player,quest,chosen,16);assertTrue(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));assertFalse(s.recoverItem(new EconomyStore.Receipt(s.id(),pending.sequence())));s.archive(UUID.randomUUID(),"Grouped native potion canonical archive regression");var reopened=EconomyStore.open(path);assertEquals(1000,reopened.professions(player).track(Profession.ALCHEMIST).xp());assertEquals(8,water.entrySet().stream().filter(e->reopened.matchesNativeOutput(e.getKey(),player,quest,e.getValue())).count());assertThrows(IllegalStateException.class,()->reopened.prepareNativeOutputDelivery(UUID.randomUUID(),player,quest,chosen,16));}
}
